def bis(f, lo, hi, n=200):
    flo = f(lo)
    for _ in range(n):
        m = (lo + hi) / 2
        fm = f(m)
        if (flo <= 0) == (fm <= 0):
            lo, flo = m, fm
        else:
            hi = m
    return (lo + hi) / 2

def _area(a):
    xa = bis(lambda x: a**(x+3) - a**(-x+3), -20, 20)
    ya = a**(xa+3)
    xb = bis(lambda x: a**(x+3) - 1, -20, 20)
    xc = bis(lambda x: a**(-x+3) - 1, -20, 20)
    return abs((xb-xa)*(1-ya) - (xc-xa)*(1-ya)) / 2

def skill():
    h = Rational(2*24, 6)
    return (h + 1)**2

def standard():
    a = bis(lambda a: _area(a) - 24, 1.0001, 10)
    return round(a**6)

def unique():
    xs = [1.0001 + 0.02*k for k in range(400)]
    vals = [_area(x) for x in xs]
    assert all(v2 > v1 for v1, v2 in zip(vals, vals[1:]))
    return [standard()]
